; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxn (ZX Spectrum Next - direct hardware (native)), starts in normal mode
; ============================================================

			DEVICE ZXSPECTRUMNEXT		; for SAVENEX at the end
			MMU 0 5, 16			; #0000-#BFFF: pages 16-21 (banks 8, 9, 10)
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
; the ZX Spectrum Next: NTC_ZXN defined (a DEFINE - sjasmplus's IFDEF tests those, not labels)
			DEFINE NTC_ZXN
ZXN_FIRSTBANK	equ 22		; first free 16K bank (page 44), above the program/screen/low banks
ZXN_MAXBANK	equ 90		; scan range: banks 22-111 (a 2MB Next has 112 16K banks, pages 0-223; the MMU has no page past 223 - a higher page number is not RAM)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2		; #0040 (2 bytes): over the glue
ntc_bk_sp:		dw 0			; #0042: this bank's SP while another runs
ntc_bk_out:
			db #08			; #0044: ex af, af - stash A + FLAGS (carry = far-call / interrupt) to the alternate set, before the port flip clobbers A
			ld bc, #243B		; PIVOT via the MMU ports (no Z80N opcode): select MMU slot 0 (#50)
			ld a, #50
			out (c), a
			inc b			; #253B
			ld a, 16		; the hypervisor's slot-0 page; slot 0 flips HERE - next byte is the receiver
			out (c), a
ntc_bk_recv:			; now running in the hypervisor's slot 0 (A + FLAGS already in the alternate set)
			ld (ntc_bk_svd), de	; DE / HL message to slot-0 scratch (slot 0 stays the hypervisor here)
			ld (ntc_bk_svh), hl
			ld hl, ntc_bk_hpg	; the hypervisor's resting pages, slots 1-7
			ld bc, #243B		; NextReg select port (#253B = value)
			ld d, #51		; slot register 1
ntc_bk_rc1:
			ld a, d
			out (c), a		; select the slot register
			inc b			; #253B
			ld a, (hl)
			out (c), a		; = its resting page
			dec b			; #243B
			inc hl
			inc d
			ld a, d
			cp #58			; slots #51..#57 (1..7) done? (clobbers flags - carry safe in AF\')
			jr nz, ntc_bk_rc1
			ld de, (ntc_bk_svd)
			ld hl, (ntc_bk_svh)
			db #08			; ex af, af - A + FLAGS back (IX untouched throughout = also preserved)
ntc_bk_land:
			ld sp, (ntc_bk_sp)	; the hypervisor's own SP
			ret				; to where it handed over (Run's rn_back), A/DE/IX + carry intact
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_bk_svd:		dw 0		; DE / HL message held across the slot 1-7 remap
ntc_bk_svh:		dw 0
ntc_bk_hpg:		db 17, 18, 19, 20, 21, 10, 11	; hypervisor resting pages, slots 1-7 (boot MMU map)
ntc_start2:
ntc_bk_cold:
			di
			ld sp, #C000		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Cls
			dw kw_cls

			; 22: Print "VB self test 6"
			dw kw_printzoscii
			dw glyph_56, glyph_42, glyph_20, glyph_73, glyph_65, glyph_6C, glyph_66, glyph_20
			dw glyph_74, glyph_65, glyph_73, glyph_74, glyph_20, glyph_36, 1, 0		; "VB self test 6\n"

			; 25: For i = 0 To 9
			dw kw_ztov, var_i
for1_t:

			; 26: buf(i) = i * 30
			dw kw_mulvl, var_i, 30, tmp1
			dw kw_aset8, arr_buf, var_i, tmp1

			; 27: Next
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; 28: Chk buf(9), 14          ' 270 And 255
			dw kw_lptrtov8, arr_buf+9, tmp0
			dw p_chk_c, tmp0, lit_14

			; 29: Chk buf(2), 60
			dw kw_lptrtov8, arr_buf+2, tmp0
			dw p_chk_c, tmp0, lit_60

			; 30: i = 3
			dw kw_ltov, 3, var_i

			; 31: Chk buf(i), 90
			dw kw_aget8, arr_buf, var_i, tmp0
			dw p_chk_c, tmp0, lit_90

			; 32: buf(0) = 255
			dw kw_ltolptr8, 255, arr_buf

			; 33: Chk buf(0), 255
			dw kw_lptrtov8, arr_buf, tmp0
			dw p_chk_c, tmp0, lit_255

			; 34: Chk ByteSum(buf), 255 + 30 + 60 + 90 + 120 + 150 + 180 + 210 + 240 + 14
			dw p_bytesum_c, ad_arr_buf
			dw kw_vtov, var_bytesum_bytesum, tmp0
			dw p_chk_c, tmp0, lit_1349

			; 37: ReDim dyn(5)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 6, 1

			; 38: Chk UBound(dyn), 5
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_5

			; 39: Chk LBound(dyn), 0
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_0

			; 40: For i = 0 To 5
			dw kw_ztov, var_i
for2_t:

			; 41: dyn(i) = i * i
			dw kw_mulvv, var_i, var_i, tmp2
			dw kw_pset, pa_dyn, var_i, tmp2

			; 42: Next
			dw kw_next1l_n, var_i, 5, for2_t
for2_e:

			; 43: Chk dyn(5), 25
			dw kw_pget, pa_dyn, lit_5, tmp0
			dw p_chk_c, tmp0, lit_25

			; 44: ReDim Preserve dyn(BIGN)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 21, 0

			; 45: Chk UBound(dyn), 20
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_20

			; 46: Chk dyn(4), 16
			dw kw_pget, pa_dyn, lit_4, tmp0
			dw p_chk_c, tmp0, lit_16

			; 47: dyn(20) = 7
			dw kw_pset, pa_dyn, lit_20, lit_7

			; 48: Chk dyn(20), 7
			dw kw_pget, pa_dyn, lit_20, tmp0
			dw p_chk_c, tmp0, lit_7

			; 49: ReDim dyn(1 To 3)
			dw kw_redim, pa_dyn, pa_dyn_data, 1, 2, 3, 1

			; 50: Chk LBound(dyn), 1
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_1

			; 51: Chk dyn(1), 0           ' cleared without Preserve
			dw kw_pget, pa_dyn, lit_1, tmp0
			dw p_chk_c, tmp0, lit_0

			; 52: dyn(3) = 9
			dw kw_pset, pa_dyn, lit_3, lit_9

			; 53: Chk Total(dyn), 9
			dw p_total_c, pa_dyn
			dw kw_vtov, var_total_total, tmp0
			dw p_chk_c, tmp0, lit_9

			; 54: Erase dyn
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 0, 0

			; 55: Chk UBound(dyn), -1
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 57: ReDim names(2)
			dw kw_redim, pa_names, pa_names_data, 0, 41, 3, 1

			; 58: names(1) = "dyn"
			dw kw_psets, pa_names, lit_1, str0

			; 59: Chk Len(names(1)), 3
			dw kw_pget, pa_names, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw p_chk_c, tmp0, lit_3

			; 60: ReDim big(1)
			dw kw_redim, pa_big, pa_big_data, 0, 4, 2, 1

			; 61: big(1) = 100000
			dw kw_pset, pa_big, lit_1, llit_100000

			; 62: Chk big(1) \ 1000, 100
			dw kw_pget, pa_big, lit_1, ltmp0
			dw kw_l_div, ltmp0, llit_1000, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_100

			; 65: fixed(2) = 5
			dw kw_ltov, 5, arr_fixed+4

			; 66: Erase fixed
			dw kw_erase, arr_fixed, 10

			; 67: Chk fixed(2), 0
			dw p_chk_c, arr_fixed+4, lit_0

			; 70: ReDim recs(2)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 3, 1
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 3, 1

			; 71: For i = 0 To 2
			dw kw_ztov, var_i
for3_t:

			; 72: recs(i).n = i * 5
			dw kw_mulvl, var_i, 5, tmp2
			dw kw_pset, pa_recs_n, var_i, tmp2

			; 73: recs(i).nm = "r" & i
			dw kw_strcstr, stmp3, var_i
			dw kw_strcpy, stmp2, str1
			dw kw_strcat, stmp2, stmp3
			dw kw_psets, pa_recs_nm, var_i, stmp2

			; 74: Next
			dw kw_next1l_n, var_i, 2, for3_t
for3_e:

			; 75: Chk UBound(recs), 2
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_2

			; 76: Chk Len(recs(1).nm) + recs(2).n, 12
			dw kw_pget, pa_recs_nm, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw kw_pget, pa_recs_n, lit_2, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw p_chk_c, tmp0, lit_12

			; 77: ReDim Preserve recs(4)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 5, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 5, 0

			; 78: Chk recs(2).n, 10
			dw kw_pget, pa_recs_n, lit_2, tmp0
			dw p_chk_c, tmp0, lit_10

			; 79: Erase recs
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 0, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 0, 0

			; 80: Chk UBound(recs), -1
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 82: Print
			dw kw_printnl

			; 83: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printzoscii
			dw glyph_20, glyph_74, glyph_65, glyph_73, glyph_74, glyph_73, glyph_2C, glyph_20
			dw 0		; " tests, "
			dw kw_printint, var_bad
			dw kw_printzoscii
			dw glyph_20, glyph_66, glyph_61, glyph_69, glyph_6C, glyph_65, glyph_64, 1
			dw 0		; " failed\n"

			; 84: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 87: t = t + 1
			dw kw_inc, var_t

			; 88: Print t; ":";
			dw kw_printint, var_t
			dw kw_printzoscii
			dw glyph_3A, 0		; ":"

			; 89: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if4_1

			; 90: Print "ok ";
			dw kw_printzoscii
			dw glyph_6F, glyph_6B, glyph_20, 0		; "ok "

			; 91: Else
			dw if4_e_go
if4_1:

			; 92: Print "FAIL("; got; ") ";
			dw kw_printzoscii
			dw glyph_46, glyph_41, glyph_49, glyph_4C, glyph_28, 0		; "FAIL("
			dw kw_printint, var_chk_got
			dw kw_printzoscii
			dw glyph_29, glyph_20, 0		; ") "

			; 93: bad = bad + 1
			dw kw_inc, var_bad

			; 94: End If
if4_e:
			dw p_chk_r

; ============================================================
; function bytesum (normal mode)
; ============================================================

p_bytesum:

			; 98: Dim k As Integer

			; 99: ByteSum = 0
			dw kw_ztov, var_bytesum_bytesum

			; 100: For k = LBound(b) To UBound(b)
			dw kw_lbound, pa_bytesum_b, var_bytesum_k
			dw kw_ubound, pa_bytesum_b, for5_l
			dw kw_forupv_n, var_bytesum_k, for5_l, for5_e
for5_t:

			; 101: ByteSum = ByteSum + b(k)
			dw kw_ztov, tmp1
			dw kw_pget, pa_bytesum_b, var_bytesum_k, tmp1
			dw kw_add, var_bytesum_bytesum, tmp1, var_bytesum_bytesum

			; 102: Next
			dw kw_next1v_n, var_bytesum_k, for5_l, for5_t
for5_e:
			dw p_bytesum_r

; ============================================================
; function total (normal mode)
; ============================================================

p_total:

			; 106: Dim k As Integer

			; 107: Total = 0
			dw kw_ztov, var_total_total

			; 108: For k = LBound(a) To UBound(a)
			dw kw_lbound, pa_total_a, var_total_k
			dw kw_ubound, pa_total_a, for6_l
			dw kw_forupv_n, var_total_k, for6_l, for6_e
for6_t:

			; 109: Total = Total + a(k)
			dw kw_pget, pa_total_a, var_total_k, tmp1
			dw kw_add, var_total_total, tmp1, var_total_total

			; 110: Next
			dw kw_next1v_n, var_total_k, for6_l, for6_t
for6_e:
			dw p_total_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			ld sp, if4_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_bytesum_c:		; call bytesum (normal)
			pop hl			; b() descriptor
			ld de, pa_bytesum_b
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_bytesum_bytesum), hl
			ld hl, 0
			ld (var_bytesum_k), hl
			ld (p_bytesum_rs), sp
			ld sp, p_bytesum
			jp ntc_xn
p_bytesum_r:		; end of bytesum
			ld sp, (p_bytesum_rs)
			jp ntc_xn
p_total_c:		; call total (normal)
			pop hl			; a() descriptor
			ld de, pa_total_a
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_total_total), hl
			ld hl, 0
			ld (var_total_k), hl
			ld (p_total_rs), sp
			ld sp, p_total
			jp ntc_xn
p_total_r:		; end of total
			ld sp, (p_total_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
ad_arr_buf:			dw arr_buf, 0, 0, 10, 1, 1		; array as an argument
var_bytesum_bytesum:			dw 0
var_total_total:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_bytesum_rs:			dw 0
var_bytesum_k:			dw 0
for5_l:			dw 0
p_total_rs:			dw 0
var_total_k:			dw 0
for6_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
			db 40			; capacity
stmp0:			ds 41
			db 40			; capacity
stmp1:			ds 41
			db 40			; capacity
stmp2:			ds 41
			db 40			; capacity
stmp3:			ds 41
ltmp0:			dw 0, 0

